class SumTask extends RecursiveTask<Long> {
    protected Long compute() {
        if (end - start <= THRESHOLD) { /* licz bezposrednio */ }
        int mid = start + (end-start)/2;
        SumTask left = new SumTask(array, start, mid);
        SumTask right = new SumTask(array, mid, end);
        left.fork(); // oddaj do puli
        long rightResult = right.compute(); // policz prawa w BIEZACYM watku
        long leftResult = left.join(); // czekaj na lewa
        return leftResult + rightResult;
    }
}

class DoubleAction extends RecursiveAction {
    protected void compute() {
        if (end - start <= THRESHOLD) { /* modyfikuj bezposrednio */ return; }
        int mid = start + (end-start)/2;
        DoubleAction left = new DoubleAction(array, start, mid);
        DoubleAction right = new DoubleAction(array, mid, end);
        invokeAll(left, right); // forkuje i joinuje OBIE naraz
    }
}

