class SumTask extends RecursiveTask<Long> {
    long[] tab; int start, end;
    SumTask(long[] t, int s, int e) { tab=t; start=s; end=e; }
    protected Long compute() {
        if (end-start <= 100) { long suma=0; for (int i=start;i<end;i++) suma+=tab[i]; return suma; }
        int mid = start+(end-start)/2;
        SumTask l = new SumTask(tab,start,mid), r = new SumTask(tab,mid,end);
        l.fork();
        long prawa = r.compute();
        long lewa = l.join();
        return lewa+prawa;
    }
}
