class MaxTask extends RecursiveTask<Integer> {
    int[] tab; int start, end;
    MaxTask(int[] t, int s, int e) { tab=t; start=s; end=e; }
    protected Integer compute() {
        if (end-start <= 50) { int max=Integer.MIN_VALUE; for (int i=start;i<end;i++) max=Math.max(max,tab[i]); return max; }
        int mid = start+(end-start)/2;
        MaxTask l = new MaxTask(tab,start,mid), r = new MaxTask(tab,mid,end);
        l.fork();
        int prawy = r.compute();
        int lewy = l.join();
        return Math.max(lewy, prawy);
    }
}
