class ProductTask extends RecursiveTask<Long> {
    int start, end;
    ProductTask(int s, int e) { start=s; end=e; }
    protected Long compute() {
        if (end-start <= 5) { long p=1; for (int i=start;i<=end;i++) p*=i; return p; }
        int mid = start+(end-start)/2;
        ProductTask l = new ProductTask(start,mid), r = new ProductTask(mid+1,end);
        l.fork();
        long prawy = r.compute();
        long lewy = l.join();
        return lewy*prawy;
    }
}
