class ParallelMergeSort extends RecursiveAction {
    int[] tab; int start, end;
    ParallelMergeSort(int[] t, int s, int e) { tab=t; start=s; end=e; }
    protected void compute() {
        if (end-start <= 20) { Arrays.sort(tab, start, end); return; }
        int mid = start+(end-start)/2;
        invokeAll(new ParallelMergeSort(tab,start,mid), new ParallelMergeSort(tab,mid,end));
        int[] merged = new int[end-start];
        int i=start, j=mid, k=0;
        while (i<mid && j<end) merged[k++] = tab[i]<=tab[j] ? tab[i++] : tab[j++];
        while (i<mid) merged[k++]=tab[i++];
        while (j<end) merged[k++]=tab[j++];
        System.arraycopy(merged, 0, tab, start, merged.length);
    }
}
