class IsSortedTask extends RecursiveTask<Boolean> {
    int[] tab; int start, end;
    IsSortedTask(int[] t, int s, int e) { tab=t; start=s; end=e; }
    protected Boolean compute() {
        if (end-start <= 10) { for (int i=start+1;i<end;i++) if (tab[i]<tab[i-1]) return false; return true; }
        int mid = start+(end-start)/2;
        IsSortedTask l = new IsSortedTask(tab,start,mid), r = new IsSortedTask(tab,mid,end);
        l.fork();
        boolean prawaOk = r.compute();
        boolean lewaOk = l.join();
        boolean granicaOk = tab[mid-1] <= tab[mid];
        return lewaOk && prawaOk && granicaOk;
    }
}
