class ParallelQuickSort extends RecursiveAction {
    int[] tab; int lo, hi;
    ParallelQuickSort(int[] t, int lo, int hi) { tab=t; this.lo=lo; this.hi=hi; }
    protected void compute() {
        if (hi-lo <= 50) { Arrays.sort(tab, lo, hi+1); return; }
        int p = partition(tab, lo, hi);
        invokeAll(new ParallelQuickSort(tab,lo,p-1), new ParallelQuickSort(tab,p+1,hi));
    }
    static int partition(int[] tab, int lo, int hi) {
        int pivot = tab[hi]; int i = lo-1;
        for (int j=lo;j<hi;j++) if (tab[j]<pivot) { i++; int tmp=tab[i]; tab[i]=tab[j]; tab[j]=tmp; }
        int tmp=tab[i+1]; tab[i+1]=tab[hi]; tab[hi]=tmp;
        return i+1;
    }
}
