record Stats(int min, int max, long suma, int liczba) {
    static Stats merge(Stats a, Stats b) { return new Stats(Math.min(a.min,b.min), Math.max(a.max,b.max), a.suma+b.suma, a.liczba+b.liczba); }
}
class StatsTask extends RecursiveTask<Stats> {
    int[] tab; int start, end;
    StatsTask(int[] t, int s, int e) { tab=t; start=s; end=e; }
    protected Stats compute() {
        if (end-start <= 100) { int min=Integer.MAX_VALUE, max=Integer.MIN_VALUE; long suma=0; for (int i=start;i<end;i++) { min=Math.min(min,tab[i]); max=Math.max(max,tab[i]); suma+=tab[i]; } return new Stats(min,max,suma,end-start); }
        int mid = start+(end-start)/2;
        StatsTask l = new StatsTask(tab,start,mid), r = new StatsTask(tab,mid,end);
        l.fork();
        Stats prawy = r.compute();
        Stats lewy = l.join();
        return Stats.merge(lewy, prawy);
    }
}
