static boolean verifyAgainstSequential(int iterations) throws InterruptedException {
    Random rnd = new Random();
    for (int i=0;i<iterations;i++) {
        int rozmiar = 100 + rnd.nextInt(100000);
        long[] dane = new long[rozmiar];
        for (int j=0;j<rozmiar;j++) dane[j] = rnd.nextInt(1000);
        long sekwencyjny = 0; for (long v : dane) sekwencyjny += v;
        ForkJoinPool pool = new ForkJoinPool();
        long rownolegly;
        try { rownolegly = pool.invoke(new SumTask(dane, 0, rozmiar)); } finally { pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS); }
        if (sekwencyjny != rownolegly) return false;
    }
    return true;
}
